enum _Loc {
    Root,
    Dead,
}

struct _V<'a> {
    m: &'a mut Widths,
    stack: [_Loc; 1],
    sp: usize,
    cur: _Loc,
    dead: u16, // depth of the skipped subtree cur sits in (see sequence_begin)
    err: bool,
    inv: bool,
    askip: usize, // elements left to discard from a wire-type-contradictory array
}

